var out = [];
for (var conv = 0; conv < 24; ++conv) {
  var a = 0.4, b = 0.7, c = -0.3;
  var m = Matrix.getZRotation(c).multiply(Matrix.getYRotation(b)).multiply(Matrix.getXRotation(a));
  var angles = m.getEuler2(conv);
  var back = Matrix.getEulerRotation(angles, conv);
  var worst = 0;
  var keys = [['right','x'],['right','y'],['right','z'],['up','x'],['up','y'],['up','z'],['forward','x'],['forward','y'],['forward','z']];
  for (var i = 0; i < keys.length; ++i) {
    var d = Math.abs(m[keys[i][0]][keys[i][1]] - back[keys[i][0]][keys[i][1]]);
    if (d > worst) { worst = d; }
  }
  out.push(conv + ':' + (worst < 1e-9 ? 'ok' : 'FAIL(' + worst + ')'));
}
return JSON.stringify(out);

var aAxis = createAxis({coordinate:0, table:true, axis:[1,0,0], range:[-120,120], preference:1});
var cAxis = createAxis({coordinate:2, table:true, axis:[0,0,1], cyclic:true, preference:0});
machineConfiguration = new MachineConfiguration(aAxis, cAxis);
var dirs = [[0,0,1],[0,0.5,0.8660254037844387],[0.5,0,0.8660254037844387],
            [0.35355339059327373,0.35355339059327373,0.8660254037844387]];
var out = [];
for (var i = 0; i < dirs.length; ++i) {
  var d = new Vector(dirs[i][0], dirs[i][1], dirs[i][2]).getNormalized();
  var m = new Matrix(new Vector(1,0,0), new Vector(0,1,0), d);
  var abc = machineConfiguration.getABC(m);
  var r = machineConfiguration.getDirection(abc);
  var err = Math.max(Math.abs(r.x-d.x), Math.max(Math.abs(r.y-d.y), Math.abs(r.z-d.z)));
  out.push('A' + toDeg(abc.x).toFixed(3) + ' C' + toDeg(abc.z).toFixed(3) + ' err=' + (err < 1e-9 ? 'ok' : err));
}
return JSON.stringify(out);

var bAxis = createAxis({coordinate:1, table:true, axis:[0,1,0], range:[-120,120], preference:1});
var cAxis = createAxis({coordinate:2, table:true, axis:[0,0,1], cyclic:true, preference:0});
machineConfiguration = new MachineConfiguration(bAxis, cAxis);
var out = [];
out.push('wrap=' + toDeg(machineConfiguration.remapABC(new Vector(0,0,Math.PI*3)).z).toFixed(3));
out.push('short=' + toDeg(machineConfiguration.remapToABC(new Vector(0,0,toRad(-170)), new Vector(0,0,toRad(170))).z).toFixed(3));
var threw = 'no';
try { machineConfiguration.remapABC(new Vector(0, toRad(150), 0)); } catch (e) { threw = 'yes'; }
out.push('outOfRange=' + threw);
machineConfiguration.setMultiAxisFeedrate(FEED_INVERSE_TIME, 9999.99, INVERSE_MINUTES, 0.5, 1.0);
out.push('invTime=' + __ivacMultiAxisFeed(10, 0, 500).toFixed(3));
machineConfiguration.setMultiAxisFeedrate(FEED_DPM, 9999.99, DPM_STANDARD, 0.5, 1.0);
out.push('dpm=' + __ivacMultiAxisFeed(10, 0.2, 500).toFixed(3));
return JSON.stringify(out);
